BEGIN;
UPDATE public.records SET abstract = 'Effective communication, dissemination, and exploitation are crucial for clearly conveying research results and bridging the gap between science, policy, industry, and the public. European projects like MAMBO prioritise the effective distribution of outcomes to achieve significant societal impact. MAMBO’s strategy emphasises raising awareness and promoting activities, while dissemination ensures broad access to knowledge. Exploitation focuses on enabling stakeholders to leverage results for societal, commercial, or political purposes.' WHERE id = '64af8c06-6bbe-4fcf-91bc-110df2523aed' AND (abstract IS NULL OR length(btrim(abstract)) < 20 OR lower(btrim(abstract)) IN ('-','--','.','description','n/a','na','no abstract','no description','none','not available','null','xx'));
UPDATE public.records SET abstract = 'Lockdown measures reducing the transmission of COVID-19 have led to a temporal improvement in air quality worldwide. An assessment by Kai Chen and colleagues1 reported that a drop in air pollution in 367 Chinese cities was associated with 8911 prevented deaths because of a reduction in nitrogen dioxide (NO2; 95% CI 6950–10 866) and 3214 deaths from a reduction in PM2·5 (95% CI 2340–4087). However, the method for quantifying reductions in air pollution and attributable mortality is on the basis of several simplifications and assumptions that are likely to bias the estimates.' WHERE id = '99e583e8-a058-4a00-a716-2b06644ec927' AND (abstract IS NULL OR length(btrim(abstract)) < 20 OR lower(btrim(abstract)) IN ('-','--','.','description','n/a','na','no abstract','no description','none','not available','null','xx'));
-- COMMIT;
